import { Route } from '@angular/router';
import { describe, expect, it } from 'vitest';

import { PROJ_ROUTES } from './proj.routes';

/**
 * proj.routes.spec.ts — contract test for PROJ_ROUTES.
 *
 * Updated from the original generated by fe-nx-register-module.py to account
 * for the deliberate wrapper-route pattern in proj.routes.ts.
 *
 * Contract the shell relies on:
 *   - The route table exists and is non-empty.
 *   - Every route declares a path (string).
 *   - Every route is either:
 *       (a) lazy — declares loadComponent / loadChildren, or a redirectTo; OR
 *       (b) a wrapper — declares `children`, in which case every child must
 *           satisfy (a) or (b) recursively.
 *     This preserves the original intent (catch any genuinely non-lazy route)
 *     while allowing the wrapper route that scopes providers within the lazy
 *     chunk (see proj.routes.ts for the rationale).
 *   - No duplicate paths at the top level or within any children array.
 *
 * What breaks the shell if this contract is violated:
 *   - A non-lazy, non-wrapper route forces the app to eagerly load the module,
 *     defeating the intent of loadChildren in app.routes.ts.
 *   - Duplicate paths cause Angular Router to silently ignore one of them.
 */

/**
 * Returns true when a route is valid:
 *   - lazy (loadComponent / loadChildren) or a redirect; OR
 *   - a wrapper with at least one child, where every child is also valid.
 *
 * A wrapper with no children is NOT valid — it would be a dead end with no
 * lazy payload, which is a configuration error.
 */
function isValidRoute(route: Route): boolean {
  const isLazy =
    typeof route.loadComponent === 'function' ||
    typeof route.loadChildren === 'function' ||
    typeof route.redirectTo === 'string';
  if (isLazy) return true;

  // Wrapper pattern: provides DI tokens within the lazy chunk scope; the
  // actual laziness lives in the children.
  if (Array.isArray(route.children) && route.children.length > 0) {
    return route.children.every(isValidRoute);
  }

  return false;
}

/** Asserts no duplicates within a single level (string comparison on path). */
function assertNoDuplicatePaths(routes: Route[], level: string): void {
  const paths = routes.map(r => r.path ?? '');
  expect(new Set(paths).size, `duplicate paths at ${level}`).toBe(paths.length);
}

describe('@cordele/proj route contract', () => {
  it('exposes at least one route', () => {
    expect(Array.isArray(PROJ_ROUTES)).toBe(true);
    expect(PROJ_ROUTES.length).toBeGreaterThan(0);
  });

  it('every top-level route declares a path', () => {
    for (const route of PROJ_ROUTES) {
      expect(typeof route.path).toBe('string');
    }
  });

  it('every route is lazy, redirects, or is a wrapper with lazy children', () => {
    for (const route of PROJ_ROUTES) {
      expect(isValidRoute(route)).toBe(true);
    }
  });

  it('has no duplicate paths at the top level', () => {
    assertNoDuplicatePaths(PROJ_ROUTES, 'top level');
  });

  it('has no duplicate paths among children of any wrapper route', () => {
    for (const route of PROJ_ROUTES) {
      if (Array.isArray(route.children)) {
        assertNoDuplicatePaths(route.children, `children of path="${route.path}"`);
      }
    }
  });
});
